import { TypedSupabaseClient } from '@/utils/supabase/client';

/** Bulk clock-in for today. Timestamps are generated by the database. */
export async function clockInChildren(client: TypedSupabaseClient, childIds: string[]): Promise<void> {
  const { error } = await client.rpc('clock_in_children', { child_ids: childIds });

  if (error) {
    throw new Error(`Failed to clock in children: ${error.message}`);
  }
}
